/* FireRisk Intelligence dashboard 0.8 — talks only to the local backend (/api). No sample data.
   Every user-facing string is English. Source records keep their original (Vietnamese) text in the data; the UI shows
   the English display text from the API, marks AI translations, and never shows untranslated text by default. */
"use strict";

const $ = (s, el = document) => el.querySelector(s);
const $$ = (s, el = document) => [...el.querySelectorAll(s)];
const esc = (v) => String(v ?? "").replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]));
const SEV = ["normal", "watch", "warning", "high", "emergency"];
const LABEL = { normal: "Normal", watch: "Watch", warning: "Warning", high: "High Risk", emergency: "Emergency", unknown: "No Data Available" };
const KIND = {
  incident: "Incident report", construction: "Works log", asset_service: "Repair / maintenance",
  inspection_check: "Daily checklist", generator_run: "Generator log", meter_episode: "Meter analysis",
  meter_reading: "Meter reading", vehicle_day: "Vehicle count",
};
const rank = (s) => SEV.indexOf(s);
/* Vietnamese letters (written as escapes so this file itself contains no Vietnamese text) */
const VI_RE = /[\u00C0-\u00D6\u00D8-\u00F6\u00F8-\u1EF9\u0110\u0111]/;
const roman = (s) => String(s ?? "").replace(/\u0110/g, "D").replace(/\u0111/g, "d").normalize("NFD").replace(/[\u0300-\u036f]/g, "");
const PENDING = '<span class="pend" title="The English translation of this source record has not been produced yet. The original record is unchanged.">English translation pending</span>';

const ICON = {
  watch: '<svg width="13" height="13" viewBox="0 0 14 14" aria-hidden="true"><path d="M1 7s2.3-4 6-4 6 4 6 4-2.3 4-6 4-6-4-6-4z" fill="none" stroke="currentColor" stroke-width="1.6"/><circle cx="7" cy="7" r="1.8" fill="currentColor"/></svg>',
  warning: '<svg width="13" height="13" viewBox="0 0 14 14" aria-hidden="true"><path d="M7 1.5l6 11H1z" fill="currentColor" opacity=".25" stroke="currentColor" stroke-width="1.4" stroke-linejoin="round"/><path d="M7 5.5v3.3" stroke="currentColor" stroke-width="1.7" stroke-linecap="round"/><circle cx="7" cy="10.6" r=".9" fill="currentColor"/></svg>',
  high: '<svg width="13" height="13" viewBox="0 0 14 14" aria-hidden="true"><path d="M4.3 1h5.4L13 4.3v5.4L9.7 13H4.3L1 9.7V4.3z" fill="currentColor" opacity=".3" stroke="currentColor" stroke-width="1.3"/><path d="M7 3.8v4" stroke="currentColor" stroke-width="1.8" stroke-linecap="round"/><circle cx="7" cy="10" r="1" fill="currentColor"/></svg>',
  emergency: '<svg width="13" height="13" viewBox="0 0 14 14" aria-hidden="true"><path d="M7 1c1 2.8 4.3 4.5 4.3 8.2A4.3 4.3 0 0 1 2.7 9.2C2.7 7 4 6 4.7 4.3c.6 1.6 1.4 2.2 2.2 2.4C7.2 5 7.4 3 7 1z" fill="currentColor"/></svg>',
  unknown: '<svg width="13" height="13" viewBox="0 0 14 14" aria-hidden="true"><circle cx="7" cy="7" r="6" fill="none" stroke="currentColor" stroke-width="1.5" stroke-dasharray="2.2 1.6"/></svg>',
};
ICON.normal = ICON.unknown;
const lvl = (s, big) => `<span class="lvl ${esc(s)}${big ? " lg" : ""}">${ICON[s] || ""}${esc(LABEL[s] || s)}</span>`;
const ORG = { source: ["SOURCE", "Read directly from a source record"], derived: ["DERIVED", "Calculated from source data by a documented method"],
  rule: ["RULE", "Result of the deterministic rule set"], ai: ["AI · MUSE SPARK", "Interpretation or hypothesis generated by Muse Spark"],
  ai_vision: ["AI · VIDEO", "Observation generated by Muse Spark from a survey video"], test: ["TEST", "Produced against a mock / test endpoint"] };
const org = (k, txt) => `<span class="org ${k === "ai_vision" ? "ai" : k}" title="${esc((ORG[k] || [])[1] || "")}">${esc(txt || (ORG[k] || [k])[0])}</span>`;
const day = (iso) => (iso ? new Date(iso).toLocaleDateString("en-GB", { day: "2-digit", month: "short", year: "numeric" }) : "undated");
const dt = (iso) => (iso ? new Date(iso).toLocaleString("en-GB", { day: "2-digit", month: "short", hour: "2-digit", minute: "2-digit" }) : "—");
const chip = (id) => { const t = roman(id); return `<button class="chip" data-ev="${esc(id)}" title="Open source record">${esc(t.length > 30 ? t.slice(0, 28) + "…" : t)}</button>`; };
const fmtTime = (s) => `${Math.floor(s / 60)}:${String(Math.floor(s % 60)).padStart(2, "0")}`;
/* "mentioned in <record IDs>" (rule text) -> record chips */
const basisTxt = (b) => (b && b.startsWith("mentioned in ") ? `mentioned in ${b.slice(13).split(", ").map(chip).join("")}` : esc(b || ""));
const cap = (s) => (s ? s.charAt(0).toUpperCase() + s.slice(1) : s);

async function api(path, opts) {
  const r = await fetch(path, opts);
  if (!r.ok) throw new Error(`${r.status} ${await r.text()}`);
  return r.json();
}

/* ---------- English display helpers ---------- */
/* Source field with its English display text. AI translations are marked; untranslated text is never shown. */
function tr(o, k) {
  const v = o?.[k];
  if (v == null || v === "") return "";
  const en = o[`${k}_en`], origin = o[`${k}_en_origin`];
  if (en && !VI_RE.test(en)) return origin === "ai_translation" ? `${esc(en)}<span class="tl" title="Translated from the original Vietnamese record by Muse Spark. The original is kept unchanged and is shown in the source record.">translated</span>` : esc(en);
  if (!VI_RE.test(String(v))) return esc(v);
  return PENDING;
}
/* Plain English text of a source field (no markup), or null when only untranslated text exists. */
const plain = (o, k) => { const en = o?.[`${k}_en`]; if (en && !VI_RE.test(en)) return en; const v = o?.[k]; return v && !VI_RE.test(String(v)) ? String(v) : null; };
/* A name (equipment, room) for display. */
const nm = (name, en, fallback = "Name not available in English yet") => (en && !VI_RE.test(en) ? en : name && !VI_RE.test(name) ? name : fallback);
/* AI output: shown only when it is English (older analyses could quote Vietnamese record wording). */
const aiT = (s) => (s == null || s === "" ? "" : VI_RE.test(String(s)) ? '<span class="pend" title="Older AI text that quoted untranslated record wording. A new English analysis replaces it.">AI text not shown: not in English</span>' : esc(s));

/* Last line of defence for the English-only rule: any untranslated text that reaches the page outside an explicit
   "original record" section is replaced by a visible marker and reported in the console (tests require 0). */
window.__viReplaced = 0;
function enforceEnglish(root) {
  if (!root) return;
  const w = document.createTreeWalker(root, NodeFilter.SHOW_TEXT);
  const hits = [];
  for (let n = w.nextNode(); n; n = w.nextNode()) {
    if (VI_RE.test(n.nodeValue) && !n.parentElement.closest('[lang="vi"],script,style')) hits.push(n);
  }
  const texts = hits.map((n) => n.nodeValue);
  hits.forEach((n) => { const s = document.createElement("span"); s.className = "pend"; s.textContent = "English text unavailable"; n.replaceWith(s); });
  $$("[title],[placeholder],[aria-label]", root).forEach((el) => {
    if (el.closest('[lang="vi"]')) return;
    ["title", "placeholder", "aria-label"].forEach((a) => { const v = el.getAttribute(a); if (v && VI_RE.test(v)) { el.setAttribute(a, a === "title" ? "Original record text is available in the source record" : "—"); hits.push(el); } });
  });
  $$("input,textarea", root).forEach((el) => { if (el.value && VI_RE.test(el.value) && !el.closest('[lang="vi"]')) { el.value = ""; hits.push(el); } });
  if (hits.length) {
    window.__viReplaced += hits.length;
    console.warn(`[english-only] replaced ${hits.length} untranslated text node(s)`, hits.slice(0, 5).map((h) => (h.nodeValue || h.outerHTML || "").slice(0, 80)));
  }
}
const enObserver = new MutationObserver((muts) => {
  const roots = new Set(muts.map((m) => { const el = m.target.nodeType === 1 ? m.target : m.target.parentElement; return el?.closest("#app,#drawer,header") || el; }).filter(Boolean));
  roots.forEach(enforceEnglish);
});

/* ---------- labels ---------- */
const ZSHORT = { Roof: "Roof", F4: "Floor 4", F3: "Floor 3", F2: "Floor 2", F1: "Floor 1", B1: "Basement B1", Building: "Whole building", "": "Location not recorded" };
const zshort = (z) => ZSHORT[z || ""] || z;
const STATUS_TXT = { new: "Open", acknowledged: "Acknowledged", investigating: "Investigating", confirmed: "Confirmed on Site", resolved: "Resolved", false_alarm: "False Alarm" };
const stat = (a) => esc(STATUS_TXT[a.verification?.status || a.status || "new"] || a.status);
const isActive = (a) => !["resolved", "false_alarm"].includes(a.verification?.status);
const RTYPE = { water_electrical: "Water in electrical rooms", detection_impairment: "Fire detection", motor_overheat: "Motor overheating", backup_power: "Standby power", fire_water: "Fire-fighting water", smoke_control: "Smoke exhaust", pa_system: "Evacuation announcements", fire_event: "Fire or smoke reported", electrical_anomaly: "Electrical pattern", consumption_anomaly: "Consumption pattern" };
const riskStatus = (r) => r.open ? '<span class="rst open">Unresolved</span>' : '<span class="rst fixed">Marked fixed in records</span>';
const SRCNAME = { ops_data: "Operations data", vehicles: "Visitor & vehicle counts" };
const AI_CLS = { done: "done", running: "running", failed: "failed", not_analysed: "none" };
function aiPill(st, withFallback) {
  if (!st) return "";
  const test = st.code === "done" && st.api_mode === "test" ? ' <b title="Result from a mock / test endpoint, not Muse Spark">· TEST</b>' : "";
  const main = `<span class="aist ${AI_CLS[st.code] || "none"}" title="${esc(st.label_en)}">${st.code === "running" ? '<span class="spinner"></span>' : ""}${esc(st.label)}${test}</span>`;
  const fb = withFallback && st.fallback ? ` <span class="aist rulefb" title="${esc(st.fallback_label_en)}">${esc(st.fallback_label)}</span>` : "";
  return main + fb;
}

let S = null;
async function loadStatus() {
  S = await api("/api/status");
  $("#building").textContent = roman(S.building);
  const issues = S.sources_down.length + S.sources_stale.length;
  const sy = S.sync || {};
  const drive = !sy.configured ? '<span class="hchip"><i></i>Google Drive not connected</span>'
    : sy.last && !sy.last.ok ? `<span class="hchip bad"><i></i>Drive update failed ${dt(sy.last.started_at)}</span>`
    : sy.last_ok_at ? `<span class="hchip ok"><i></i>Drive synced <b>${dt(sy.last_ok_at)}</b></span>` : '<span class="hchip"><i></i>Drive not synced yet</span>';
  $("#freshness").innerHTML = `<span class="hchip ok"><i></i>Last analysis <b>${dt(S.generated_at)}</b></span>${drive}${issues ? `<span class="hchip bad"><i></i>${issues} source issue(s)</span>` : ""}`;
  const rb = $("#refresh");
  if (!rb.disabled) rb.textContent = sy.configured ? "Update Data" : "Re-run Analysis";
  rb.title = sy.configured ? "Download the latest files from Google Drive, then re-run the analysis" : "Re-run the analysis on the current data snapshot";
  const ai = $("#ai-status");
  ai.innerHTML = `<i></i>${S.ai.configured ? (S.ai.mode === "live" ? "Muse Spark Ready" : "Muse Spark · TEST Mode") : "Muse Spark Not Configured"}`;
  ai.className = "hchip" + (S.ai.configured ? " ai" : " bad");
  ai.title = S.ai.configured ? `Model ${S.ai.model}` : "Set MODEL_API_KEY in the .env file to enable Muse Spark";
}

/* ---------- unified issues (fire-safety risks and equipment alerts keep their own classification) ---------- */
const ISS = {};
const keep = (i) => (ISS[i.issue_id] = i);
function fireIssue(r, a) {
  const place = (r.location || "").includes(" · ") ? r.location.split(" · ").slice(1).join(" · ") : r.location;
  return keep({ issue_id: `fire:${r.signal_id}`, kind: "fire_risk", kind_label: "Fire-safety risk", severity: r.severity, open: r.open,
    title: r.risk, place, zone: a.zone, zone_label: a.zone_label, count_text: r.evidence, alert_id: a.alert_id, signal_id: r.signal_id,
    status_text: r.open ? `${r.unresolved} unresolved` : "all records marked fixed", risk_type: r.risk_type, verification: a.verification, last_seen: r.last_seen });
}
function eqIssue(a) {
  const finding = (a.headline || "").includes(": ") ? a.headline.split(": ").slice(1).join(": ") : null;
  const title = nm(a.asset_name, a.asset_name_en, null) || (a.asset_id && !VI_RE.test(a.asset_id) ? a.asset_id : null);
  return keep({ issue_id: `eq:${a.alert_id}`, kind: "equipment", subkind: a.type === "meter" ? "meter" : "equipment",
    kind_label: a.type === "meter" ? "Consumption anomaly" : "Equipment fault", severity: a.severity, open: a.open_items > 0,
    title, title_pending: !title, place: title, summary: finding && !VI_RE.test(finding) ? finding : null, zone: a.zone || "",
    zone_label: a.zone_label, count_text: a.type === "meter" ? `${a.evidence_count} event${a.evidence_count === 1 ? "" : "s"}` : a.open_items ? `${a.open_items} open` : `${a.evidence_count} record(s)`,
    alert_id: a.alert_id, critical: a.critical, fire_links: (a.fire_links || []).map((l) => l.fire_alert_id), verification: a.verification, last_seen: a.last_seen });
}
const issueName = (i) => (i.title_pending ? "Equipment (name translation pending)" : i.place || i.title);
const issueDesc = (i) => (i.kind === "fire_risk" ? i.title : cap(i.summary) || i.kind_label);
function icard(i, opts = {}) {
  ISS[i.issue_id] = ISS[i.issue_id] || i;
  return `<button class="icard sv-${esc(i.severity)}" data-issue="${esc(i.issue_id)}" aria-label="${esc(`${zshort(i.zone)}, ${LABEL[i.severity]}: ${issueDesc(i)}. View details`)}">
    <span class="ic-t">${opts.noFloor ? "" : `${esc(zshort(i.zone))} · `}${esc(issueName(i))}</span>
    <span class="ic-d">${esc(issueDesc(i))}</span>
    <span class="ic-m"><span class="sevtxt ${esc(i.severity)}">${esc(LABEL[i.severity])}</span>·<span class="${i.open ? "openmark" : ""}">${esc(i.kind === "fire_risk" ? (i.open ? i.status_text : "marked fixed") : i.count_text)}</span><span class="kindtag ${esc(i.kind)}">${esc(i.kind_label)}</span>${i.critical ? '<span class="kindtag">critical</span>' : ""}</span>
    <span class="ic-go" aria-hidden="true">View Details →</span></button>`;
}
function bindIssues(root) { $$("[data-issue]", root).forEach((b) => (b.onclick = () => openIssue(ISS[b.dataset.issue]))); }
const sortIssues = (l) => [...l].sort((a, b) => rank(b.severity) - rank(a.severity) || (b.open - a.open) || ((a.kind !== "fire_risk") - (b.kind !== "fire_risk")) || String(b.last_seen || "").localeCompare(String(a.last_seen || "")));

/* ============================== Overview ============================== */
let B = null, BR = null, selFloor = null, briefIdx = 0, briefPoll = null;
async function viewOverview() {
  [B, BR] = await Promise.all([api("/api/building"), api("/api/briefing")]);
  B.floors.forEach((f) => f.issues.forEach(keep)); B.unassigned.issues.forEach(keep); BR.items.forEach(keep);
  if (selFloor && !B.floors.some((f) => f.zone === selFloor)) selFloor = null;
  briefIdx = Math.min(briefIdx, Math.max(0, BR.items.length - 1));
  const sm = B.summary;
  const bs = sm.building_state;
  const floorsN = B.floors.filter((f) => f.zone !== "Building").length;
  $("#app").innerHTML = `
    ${sm.sources_down.length ? `<div class="warnbox"><b>Data source problem.</b> ${sm.sources_down.map((x) => esc(`${x.source}: ${x.error}`)).join("; ")}. Results may be incomplete. <a href="#/data">Data &amp; Evidence</a></div>` : ""}
    <section id="brief" class="brief" aria-label="AI Risk Briefing" aria-live="polite"></section>
    <section class="kpis" aria-label="Building summary">
      <div class="kpi k-${esc(bs)}" title="${esc(sm.building_state_rule)}"><span class="kicker">Building condition</span><span class="v">${ICON[bs] || ""}${esc(sm.building_state_label)}</span><span class="d">${sm.floors_not_assessed.length ? `${sm.floors_not_assessed.length} floor(s) not assessed` : "Highest level among active issues"}</span></div>
      <div class="kpi k-urgent"><span class="kicker">High-priority issues</span><span class="v num">${sm.high_priority}</span><span class="d">open, High Risk or Emergency · of ${sm.issues_active} active</span></div>
      <div class="kpi"><span class="kicker">Floors with issues</span><span class="v num">${sm.floors_with_issues}<small class="muted" style="font-size:14px">/ ${floorsN}</small></span><span class="d">${B.floors.find((f) => f.zone === "Building")?.issue_count ? `+ ${B.floors.find((f) => f.zone === "Building").issue_count} building-wide` : "no building-wide issue"}${B.unassigned.issues.length ? ` · ${B.unassigned.issues.length} without location` : ""}</span></div>
      <div class="kpi"><span class="kicker">Unresolved records</span><span class="v num">${sm.issues_unresolved}</span><span class="d">issues with an open source record</span></div>
      <div class="kpi"><span class="kicker">Latest analysis</span><span class="v sm">${dt(sm.last_analysis)}</span><span class="d">${sm.last_drive_sync_ok ? `Drive synced ${dt(sm.last_drive_sync_ok)}` : "Drive not synced yet"}</span></div>
    </section>
    <div class="mapgrid">
      <section class="panel mappanel" aria-labelledby="map-h"><div class="ph"><h2 id="map-h">Building Risk Map</h2><span class="small muted">Select a floor or a risk marker</span></div>
        <div id="bmap"></div>
        <div class="legend"><span><i class="lg-red"></i>High Risk / Emergency</span><span><i class="lg-warning"></i>Warning</span><span><i class="lg-watch"></i>Watch</span><span><i class="lg-none sq"></i>No active alert</span><span><i class="lg-na sq"></i>Not assessed</span><span class="muted">Number = active issues on the floor</span></div>
        ${B.unassigned.issues.length ? `<div class="unassigned"><span class="kicker">Location not recorded</span>${B.unassigned.issues.map((i) => icard(i)).join("")}</div>` : ""}
        <p class="coverage">${esc(sm.coverage_note)}</p></section>
      <section class="panel ctxpanel" id="ctx" aria-live="polite"></section>
    </div>
    <section class="panel" style="margin-top:16px"><div class="ph"><h2>Survey video findings · Muse Spark</h2><a href="#/media">Photos &amp; Videos →</a></div>
      <p class="tiny muted" style="margin:-4px 0 10px">${org("ai_vision")}Observations made by Muse Spark from the real survey videos. A video shows what was visible when it was recorded, not the current state, and never changes a rule level.</p>
      ${videoPanel(B.recent.videos)}</section>
    <div class="supgrid">
      <section class="panel"><div class="ph"><h2>System health</h2><a href="#/equipment">Equipment &amp; Systems →</a></div>${healthPanel(sm)}</section>
      <section class="panel"><div class="ph"><h2>Recent events</h2><a href="#/events">Event History →</a></div>${recentPanel(B.recent)}</section>
      <section class="panel"><div class="ph"><h2>Data &amp; sources</h2><a href="#/data">Data &amp; Evidence →</a></div>${sourcesPanel()}</section>
    </div>`;
  renderBrief(); renderMap(); renderCtx(); bindEvidence(); bindIssues($("#app"));
  clearInterval(briefPoll);
  if (BR.items.some((x) => x.ai.running || x.ai.code === "pending")) briefPoll = setInterval(refreshBrief, 10000);
}
async function refreshBrief() {
  if (location.hash && location.hash !== "#/" && location.hash !== "#") return clearInterval(briefPoll);
  const n = await api("/api/briefing").catch(() => null);
  if (!n) return;
  const sig = (x) => x.items.map((i) => i.issue_id + i.ai.code + (i.ai.analysed_at || "")).join("|");
  if (sig(n) !== sig(BR)) { BR = n; BR.items.forEach(keep); renderBrief(); }
  if (!BR.items.some((x) => x.ai.running || x.ai.code === "pending")) clearInterval(briefPoll);
}

const AI_NOTE = {
  complete: (a) => `Muse Spark analysis completed ${dt(a.analysed_at)}${a.api_mode === "test" ? " (TEST endpoint)" : ""}.`,
  complete_older: (a) => `Real Muse Spark analysis from ${dt(a.analysed_at)}${a.api_mode === "test" ? " (TEST endpoint)" : ""}. The evidence or the analysis version has changed since; a new analysis runs automatically and replaces it.`,
  pending: () => "Muse Spark analysis is pending. The rule-based explanation is shown until it completes.",
  failed: (a) => `Muse Spark analysis failed${a.error?.kind ? ` (${a.error.kind})` : ""}. The rule-based explanation is shown.`,
  insufficient_evidence: (a) => `Muse Spark found the evidence insufficient (${dt(a.analysed_at)}).`,
  unavailable: () => "AI analysis is unavailable for this risk. The rule-based explanation is shown, based only on the source records.",
  not_applicable: () => "Muse Spark analyses fire-safety risks. Equipment alerts are explained by the rule set.",
};
const fieldTxt = (f) => (f && f.text ? `${aiT(f.text)} ${f.origin === "ai" ? org("ai", "AI") : org("rule")}` : "");
function renderBrief() {
  const el = $("#brief");
  const it = BR.items[briefIdx];
  if (!it) {
    el.className = "brief";
    el.innerHTML = `<div class="br-top"><span class="kicker">AI Risk Briefing</span></div><p class="br-title">No active issue in the current records</p>
      <p class="muted">This does not confirm that the building is safe: the data has no smoke, heat or gas sensor readings.</p>`;
    return;
  }
  el.className = `brief sv-${it.severity}`;
  const others = BR.items.filter((_, i) => i !== briefIdx);
  const moreHigh = BR.high_priority_count - (rank(it.severity) >= rank("high") && it.open ? 1 : 0);
  const cons = it.ai.code === "insufficient_evidence" ? `${esc("Insufficient evidence to determine the potential consequence. Further inspection is required.")} ${org("ai", "AI")}` : fieldTxt(it.potential_consequence);
  el.innerHTML = `
    <div class="br-top"><span class="kicker">AI Risk Briefing · Highest priority${briefIdx ? " (selected issue)" : ""}</span>
      <span class="br-tag">${esc(LABEL[it.severity])} · ${esc(zshort(it.zone))}</span><span class="kindtag ${esc(it.kind)}">${esc(it.kind_label)}</span>
      ${it.open ? '<span class="rst open">Unresolved</span>' : '<span class="rst fixed">Marked fixed in records</span>'}</div>
    <div class="br-grid"><div>
      <p class="br-title">${esc(it.kind === "fire_risk" ? it.title : `${issueName(it)}: ${issueDesc(it)}`)}</p>
      <dl class="br-lines">
        <dt>Location</dt><dd>${esc(it.zone_label)}${it.place && it.kind === "fire_risk" ? ` · ${esc(it.place)}` : ""}</dd>
        ${it.observed?.text ? `<dt>Observed</dt><dd>${fieldTxt(it.observed)}</dd>` : ""}
        ${it.why_it_matters?.text ? `<dt>Why it matters</dt><dd>${fieldTxt(it.why_it_matters)}</dd>` : ""}
        ${cons ? `<dt>Potential consequence</dt><dd>${cons}</dd>` : ""}
        ${it.uncertainty?.text ? `<dt>Not established</dt><dd>${fieldTxt(it.uncertainty)}</dd>` : ""}
        ${it.first_action?.text ? `<dt>Recommended action</dt><dd class="act">${fieldTxt(it.first_action)}</dd>` : ""}
      </dl></div>
      <div class="br-side">
        <div class="row"><span>Analysis status</span><span class="aist ${esc(it.ai.code)}">${it.ai.running ? '<span class="spinner"></span>' : ""}${esc(it.ai.label)}</span></div>
        <div class="small muted">${esc(AI_NOTE[it.ai.code](it.ai))}</div>
        <div class="row"><span>Rule level</span><span>${lvl(it.severity)}</span></div>
        <div class="row"><span>Evidence</span><span>${esc(it.evidence_text || "—")}</span></div>
        <div class="br-btns">
          ${it.kind === "fire_risk" && it.ai.has_full_analysis ? '<button class="btn ai" id="br-ai" aria-expanded="false">View AI Analysis</button>' : ""}
          <button class="btn" data-issue="${esc(it.issue_id)}">View Details →</button>
          <button class="btn quiet" id="br-loc">Show on building</button></div>
      </div></div>
    ${briefAi(it)}
    <div id="br-full" class="br-more" hidden></div>
    ${others.length ? `<div class="br-more"><button class="btn quiet" id="br-others" aria-expanded="false">${moreHigh > 0 ? `${moreHigh} additional high-priority issue${moreHigh > 1 ? "s" : ""}` : "Other active issues"} · ${others.length} more ▾</button>
      <div class="br-others" id="br-list" hidden>${BR.items.map((x, i) => `<button class="br-other sv-${esc(x.severity)}${i === briefIdx ? " cur" : ""}" data-bi="${i}"><b>${esc(x.kind === "fire_risk" ? x.title : `${issueName(x)}: ${issueDesc(x)}`)}</b><span class="muted">${esc(LABEL[x.severity])} · ${esc(zshort(x.zone))} · ${esc(x.kind_label)}</span></button>`).join("")}</div></div>` : ""}`;
  bindIssues(el); bindEvidence();
  $("#br-loc").onclick = () => { selFloor = it.zone && B.floors.some((f) => f.zone === it.zone) ? it.zone : null; renderMap(); renderCtx(); $("#bmap").scrollIntoView({ behavior: "smooth", block: "center" }); };
  const ob = $("#br-others");
  if (ob) ob.onclick = () => { const l = $("#br-list"); l.hidden = !l.hidden; ob.setAttribute("aria-expanded", String(!l.hidden)); };
  $$("[data-bi]", el).forEach((b) => (b.onclick = () => { briefIdx = +b.dataset.bi; renderBrief(); renderMap(); $("#br-list") && ($("#br-list").hidden = false); }));
  const ab = $("#br-ai");
  if (ab) ab.onclick = async () => {
    const box = $("#br-full");
    if (!box.hidden) { box.hidden = true; ab.textContent = "View AI Analysis"; ab.setAttribute("aria-expanded", "false"); return; }
    ab.textContent = "Loading…";
    try { const d = await alertDetail(it.alert_id); box.innerHTML = aiFull(d, it.signal_id); box.hidden = false; ab.textContent = "Hide AI Analysis"; ab.setAttribute("aria-expanded", "true"); bindEvidence(); }
    catch (e) { box.innerHTML = `<div class="errbox">Could not load the analysis: ${esc(e.message)}</div>`; box.hidden = false; ab.textContent = "View AI Analysis"; }
  };
}

/* Real Muse Spark content shown directly in the briefing: the zone analysis and the survey-video observations. */
const URG = { immediate: "Immediately", within_24h: "Within 24 h", within_7_days: "Within 7 days", routine: "Routine" };
function briefAi(it) {
  const z = it.zone_ai, vids = it.videos || [];
  if (!z && !vids.length) return "";
  const zoneBox = z ? `<div class="aipane"><div class="aph">${org("ai")}<b>Muse Spark analysis · ${esc(zshort(it.zone))}</b><span class="tiny muted">${esc(it.ai.model || "")} · ${dt(it.ai.analysed_at)}</span></div>
      ${z.situation ? `<p class="small">${aiT(z.situation)}</p>` : ""}
      ${z.ai_priority ? `<p class="tiny muted">AI priority ${esc(LABEL[z.ai_priority] || z.ai_priority)} · rule level ${esc(LABEL[it.severity])}: ${z.agrees_with_rule ? "agrees" : "differs; the rule level stays official"}</p>` : ""}
      ${z.possible_causes.length ? `<div class="kicker" style="margin-top:6px">Possible causes for this risk (hypotheses)</div><ul class="small tight">${z.possible_causes.map((h) => `<li><span class="plaus">${esc(h.plausibility)}</span> ${aiT(h.cause)}</li>`).join("")}</ul>` : ""}
      ${z.actions.length ? `<div class="kicker" style="margin-top:6px">Checks suggested by Muse Spark</div><ul class="small tight">${z.actions.map((x) => `<li><b>${esc(URG[x.urgency] || x.urgency || "")}</b> · ${aiT(x.action)}${x.role ? ` <span class="muted">(${aiT(x.role)})</span>` : ""}</li>`).join("")}</ul>` : ""}
    </div>` : "";
  const vidBox = vids.length ? `<div class="aipane"><div class="aph">${org("ai_vision")}<b>Survey video findings · ${esc(zshort(it.zone))}</b><span class="tiny muted">what was visible when recorded</span></div>
      ${vids.map((v) => `<div class="vfind"><a href="#/video/${esc(v.video_id)}"><b>${esc(v.filename)}</b></a> <span class="tiny muted">recorded ${v.recorded_at ? dt(v.recorded_at) : "date unknown"} · ${v.observation_count} observations${v.match === "equipment" ? " · linked to this equipment in the asset register" : v.match === "room_name" ? " · same room name" : " · same floor"}</span>
        <ul class="small tight">${v.observations.map((o) => `<li><a href="#/video/${esc(v.video_id)}?t=${o.time_start_s}">${fmtTime(o.time_start_s)}</a> ${aiT(o.observation)}${o.visible_certainty === "possibly_visible" ? ' <span class="muted">(possibly visible)</span>' : ""}</li>`).join("")}</ul></div>`).join("")}
    </div>` : "";
  return `<div class="br-ai">${zoneBox}${vidBox}</div>`;
}
function videoPanel(vs) {
  if (!vs.length) return '<div class="empty">Evidence Unavailable: no survey video has been analysed yet.</div>';
  return `<div class="vgrid">${vs.map((v) => `<a class="vcard" href="#/video/${esc(v.video_id)}">
    <div class="vh"><b>${esc(v.filename)}</b><span class="tiny muted">${esc(zshort(v.zone || ""))} · recorded ${v.recorded_at ? dt(v.recorded_at) : "date unknown"} · ${v.observations} observations</span></div>
    ${v.summary ? `<p class="small vsum">${aiT(v.summary)}</p>` : ""}
    <ul class="small tight">${v.top.map((o) => `<li><span class="when">${fmtTime(o.time_start_s)}</span> ${aiT(o.observation)}</li>`).join("")}</ul></a>`).join("")}</div>`;
}

const CERT = { supported: "Supported by the records", partly_supported: "Partly supported by the records", insufficient_evidence: "Insufficient evidence" };
function aiFull(d, signalId) {
  const inv = d.investigation, r = inv && inv.status === "ok" ? inv.result : null, st = d.ai_status;
  if (!r) return `<p class="muted small">${esc(st.label)}. No Muse Spark analysis is stored for this risk yet; the rule-based explanation applies.</p>`;
  const tag = inv.api_mode === "test" ? org("test", "TEST · mock API") : org("ai");
  const b = (r.risk_briefings || []).find((x) => x.signal_id === signalId);
  const ids = (l) => (l || []).map(chip).join("") || '<span class="muted small">none</span>';
  return `<div class="aibox">
    <div class="small muted">${tag}${esc(inv.model)} · ${dt(inv.created_at)} · ${inv.trigger === "auto" ? "automatic" : "on request"}${st.result_is_current ? "" : " · <b>made on older evidence</b>"}</div>
    ${b ? `<h5>This risk</h5><dl class="dsum"><dt>Observed</dt><dd>${aiT(b.observed)} ${ids(b.evidence_ids)}</dd><dt>Why it matters</dt><dd>${aiT(b.why_it_matters)}</dd>
      <dt>Potential consequence</dt><dd>${aiT(b.potential_consequence)}</dd><dt>Certainty</dt><dd>${esc(CERT[b.certainty] || b.certainty)}</dd>
      <dt>Not established</dt><dd>${aiT(b.uncertainty)}</dd><dt>First action</dt><dd>${aiT(b.first_action)}</dd></dl>` : '<p class="small muted">This analysis has no separate briefing for this risk (made with an earlier prompt version).</p>'}
    <h5>Situation (whole zone)</h5><p class="small">${aiT(r.situation || r.summary)}</p>
    <p class="small">AI priority ${lvl(r.risk_assessment.ai_priority)} · rule level ${lvl(d.alert.severity)}: ${r.risk_assessment.agrees_with_rule_severity ? "agrees" : "differs; the rule level stays official"}. ${aiT(r.risk_assessment.rationale)}</p>
    ${r.hypotheses?.length ? `<details><summary>Possible causes: hypotheses, not confirmed (${r.hypotheses.length})</summary>${r.hypotheses.map((h) => `<div class="hyp"><span class="plaus">${esc(h.plausibility)}</span> <b>${aiT(h.cause)}</b><div class="small">${aiT(h.reasoning)}</div><div class="small muted">Supports: ${ids(h.supporting_evidence_ids)} Contradicts: ${ids(h.contradicting_evidence_ids)}</div><div class="small"><i>How to verify:</i> ${aiT(h.how_to_verify)}</div></div>`).join("")}</details>` : ""}
    ${r.scenarios?.length ? `<details><summary>Possible scenarios: not predictions (${r.scenarios.length})</summary>${r.scenarios.map((sc) => `<div class="scen"><b>${aiT(sc.scenario)}</b> <span class="plaus">${esc(sc.plausibility)}</span><div class="small">${aiT(sc.how_it_could_develop)}</div><div class="small"><i>Would confirm:</i> ${aiT(sc.what_would_confirm)}</div></div>`).join("")}</details>` : ""}
    <details><summary>Missing information and uncertainty</summary><ul class="unk">${(r.missing_information || []).map((m) => `<li><b>${aiT(m.item)}</b>: ${aiT(m.why_it_matters)}</li>`).join("")}${(r.limitations || []).map((x) => `<li>${aiT(x)}</li>`).join("")}</ul><p class="small"><b>Uncertainty:</b> ${aiT(r.uncertainty)}</p></details>
    <p class="small" style="margin-top:10px"><a href="#/fire/${esc(d.alert.alert_id)}?risk=${encodeURIComponent(signalId)}">Open the full investigation →</a></p></div>`;
}

/* ---------- Building Risk Map (SVG, front view with depth) ---------- */
const MK_COLOR = { emergency: "var(--marker)", high: "var(--marker)", warning: "var(--warning)", watch: "var(--watch)" };
const TINT = { emergency: "#EF4444", high: "#F97316", warning: "#FACC15", watch: "#60A5FA" };
function renderMap() {
  const focus = BR.items[briefIdx]?.zone;
  $("#bmap").innerHTML = buildingSvg(B.floors, focus);
  const pick = (z) => { selFloor = selFloor === z ? null : z; renderMap(); renderCtx(); };
  $$(".floor-g,.mk", $("#bmap")).forEach((g) => {
    g.addEventListener("click", (e) => { e.stopPropagation(); if (g.classList.contains("mk")) { selFloor = g.dataset.zone; renderMap(); renderCtx(); } else pick(g.dataset.zone); });
    g.addEventListener("keydown", (e) => { if (e.key === "Enter" || e.key === " ") { e.preventDefault(); g.dispatchEvent(new MouseEvent("click")); } });
  });
}
function buildingSvg(floors, focus) {
  const byZ = Object.fromEntries(floors.map((f) => [f.zone, f]));
  const narrow = window.innerWidth < 720;          // phones: tighter geometry so labels stay readable
  const W = narrow ? 480 : 760, X0 = narrow ? 128 : 190, BW = narrow ? 236 : 340, DX = narrow ? 46 : 84, DY = narrow ? -26 : -44, top = narrow ? 56 : 92;
  const H_ = narrow ? { Roof: 40, F4: 64, F3: 64, F2: 64, F1: 68, B1: 72 } : { Roof: 44, F4: 74, F3: 74, F2: 74, F1: 80, B1: 84 };
  const LX = narrow ? 30 : 70, LG = narrow ? 10 : 78;
  const order = ["Roof", "F4", "F3", "F2", "F1", "B1"];
  const ys = {}; let y = top;
  order.forEach((z) => { ys[z] = y; y += H_[z]; if (z === "F1") y += 16; });
  const ground = ys.F1 + H_.F1 + 8, H = ys.B1 + H_.B1 + 34, X1 = X0 + BW;
  const side = (yy, h) => `${X1},${yy} ${X1 + DX},${yy + DY} ${X1 + DX},${yy + h + DY} ${X1},${yy + h}`;
  const band = (z) => {
    const f = byZ[z]; if (!f) return "";
    const h = H_[z], yy = ys[z], st = f.map_state, tint = TINT[st];
    const na = st === "not_assessed", under = z === "B1";
    const mullions = z === "Roof" ? "" : Array.from({ length: Math.floor(BW / 42) }, (_, i) => `<line x1="${X0 + 21 + i * 42}" x2="${X0 + 21 + i * 42}" y1="${yy + 10}" y2="${yy + h - 10}" stroke="#22D3EE" stroke-opacity="${under ? 0.08 : 0.16}"/>`).join("")
      + `<line x1="${X0 + 8}" x2="${X1 - 8}" y1="${yy + h / 2}" y2="${yy + h / 2}" stroke="#22D3EE" stroke-opacity=".08"/>`
      + Array.from({ length: 3 }, (_, i) => { const x = X1 + (i + 1) * DX / 4; const dy = DY * (i + 1) / 4; return `<line x1="${x}" x2="${x}" y1="${yy + 10 + dy}" y2="${yy + h - 10 + dy}" stroke="#22D3EE" stroke-opacity=".10"/>`; }).join("");
    const plant = z === "Roof" ? `<rect x="${X0 + 40}" y="${yy + 10}" width="70" height="${h - 14}" rx="2" fill="#1B2640" stroke="#22D3EE" stroke-opacity=".25"/><rect x="${X0 + BW * 0.65}" y="${yy + 16}" width="44" height="${h - 20}" rx="2" fill="#1B2640" stroke="#22D3EE" stroke-opacity=".25"/>` : "";
    const sel = selFloor === z, foc = focus === z;
    const stTxt = f.issue_count ? `${f.map_state_label} · ${f.issue_count} issue${f.issue_count > 1 ? "s" : ""}` : f.map_state_label;
    const stShort = narrow && f.issue_count ? f.map_state_label : stTxt;
    const stCol = tint || (na ? "#7C89A1" : "#A8B3C7");
    const mk = f.marker ? marker(z, X0 + BW * 0.64, yy + h / 2, f) : "";
    return `<g class="floor-g${sel ? " sel" : ""}${foc ? " focus" : ""}" data-zone="${z}" role="button" tabindex="0" aria-pressed="${sel}" aria-label="${esc(zshort(z))}: ${esc(stTxt)}">
      <polygon class="ff" points="${side(yy, h)}" fill="url(#gSide)" stroke="rgba(148,163,184,.22)" ${under ? 'stroke-dasharray="5 4"' : ""}/>
      <rect class="ff" x="${X0}" y="${yy}" width="${BW}" height="${h}" fill="url(#gFront)" stroke="rgba(148,163,184,.25)" ${under ? 'stroke-dasharray="5 4"' : ""}/>
      ${tint ? `<rect x="${X0}" y="${yy}" width="${BW}" height="${h}" fill="${tint}" opacity="${rank(st) >= 3 ? 0.2 : 0.13}" pointer-events="none"/><polygon points="${side(yy, h)}" fill="${tint}" opacity="${rank(st) >= 3 ? 0.14 : 0.09}" pointer-events="none"/>` : ""}
      ${na ? `<rect x="${X0}" y="${yy}" width="${BW}" height="${h}" fill="url(#hatch)" pointer-events="none"/>` : ""}
      ${mullions}${plant}
      <line x1="${X0 - LX}" x2="${X0 - 6}" y1="${yy + h / 2}" y2="${yy + h / 2}" stroke="${foc || sel ? "#22D3EE" : "rgba(148,163,184,.3)"}" stroke-dasharray="2 4"/>
      <text class="flabel" x="${X0 - LG}" y="${yy + h / 2 - 3}" text-anchor="end" font-family="JetBrains Mono,monospace" font-size="13" font-weight="700" letter-spacing="1.5" fill="${foc || sel ? "#22D3EE" : "#F8FAFC"}">${esc(zshort(z).toUpperCase())}</text>
      <text x="${X0 - LG}" y="${yy + h / 2 + 14}" text-anchor="end" font-size="${narrow ? 12 : 11.5}" fill="${stCol}">${esc(stShort)}</text>
      ${foc ? `<text x="${X0 - LG}" y="${yy + h / 2 - 20}" text-anchor="end" font-family="JetBrains Mono,monospace" font-size="9.5" letter-spacing="1.5" fill="#D8B4FE">◆ IN AI BRIEFING</text>` : ""}
      </g>${mk}`;
  };
  const roofTop = `<polygon points="${X0},${ys.Roof} ${X0 + DX},${ys.Roof + DY} ${X1 + DX},${ys.Roof + DY} ${X1},${ys.Roof}" fill="#22304F" stroke="rgba(34,211,238,.35)"/>`;
  const bw = byZ.Building;
  const bx = X1 + DX + (narrow ? 26 : 34), by0 = ys.Roof + DY, by1 = ys.F1 + H_.F1 + DY;
  const wide = bw ? `<g class="floor-g${selFloor === "Building" ? " sel" : ""}${focus === "Building" ? " focus" : ""}" data-zone="Building" role="button" tabindex="0" aria-pressed="${selFloor === "Building"}" aria-label="Whole building: ${esc(bw.map_state_label)}${bw.issue_count ? `, ${bw.issue_count} issue(s)` : ""}">
      <rect class="ff" x="${bx - 14}" y="${by0}" width="28" height="${by1 - by0}" rx="14" fill="rgba(34,211,238,.05)" stroke="rgba(148,163,184,.28)"/>
      ${TINT[bw.map_state] ? `<rect x="${bx - 14}" y="${by0}" width="28" height="${by1 - by0}" rx="14" fill="${TINT[bw.map_state]}" opacity=".12" pointer-events="none"/>` : ""}
      <text transform="translate(${bx + 4},${(by0 + by1) / 2 + 60}) rotate(-90)" font-family="JetBrains Mono,monospace" font-size="10.5" letter-spacing="2" fill="${focus === "Building" || selFloor === "Building" ? "#22D3EE" : "#A8B3C7"}">WHOLE BUILDING</text></g>
      ${bw.marker ? marker("Building", bx, by0 + 40, bw) : ""}` : "";
  return `<svg class="bmap" viewBox="0 0 ${W} ${H}" role="group" aria-label="Building front view. Each floor can be selected; markers show active issues.">
    <defs>
      <linearGradient id="gFront" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#1E2C4A"/><stop offset="1" stop-color="#142038"/></linearGradient>
      <linearGradient id="gSide" x1="0" y1="0" x2="1" y2="0"><stop offset="0" stop-color="#18233D"/><stop offset="1" stop-color="#0F1830"/></linearGradient>
      <linearGradient id="gEarth" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#1A1F33"/><stop offset="1" stop-color="#0B1020" stop-opacity="0"/></linearGradient>
      <pattern id="hatch" width="7" height="7" patternUnits="userSpaceOnUse" patternTransform="rotate(45)"><line x1="0" y1="0" x2="0" y2="7" stroke="#3A4865" stroke-width="2"/></pattern>
      <filter id="glow" x="-80%" y="-80%" width="260%" height="260%"><feGaussianBlur stdDeviation="4" result="b"/><feMerge><feMergeNode in="b"/><feMergeNode in="SourceGraphic"/></feMerge></filter>
      <filter id="selglow" x="-10%" y="-30%" width="120%" height="160%"><feDropShadow dx="0" dy="0" stdDeviation="3" flood-color="#22D3EE" flood-opacity=".8"/></filter>
    </defs>
    <rect x="20" y="${ground}" width="${W - 40}" height="${H - ground}" fill="url(#gEarth)"/>
    ${roofTop}${order.map(band).join("")}
    <line x1="20" x2="${W - 20}" y1="${ground}" y2="${ground}" stroke="#22D3EE" stroke-opacity=".55" stroke-width="1.5"/>
    <text x="24" y="${ground - 6}" font-family="JetBrains Mono,monospace" font-size="9.5" letter-spacing="1.5" fill="#7C89A1">GROUND LEVEL</text>
    ${wide}
  </svg>`;
}
function marker(z, cx, cy, f) {
  const m = f.marker, col = MK_COLOR[m.severity] || "var(--watch)", red = rank(m.severity) >= 3;
  const label = `${zshort(z)}: ${m.count} active issue${m.count > 1 ? "s" : ""}${m.high_count ? `, ${m.high_count} High Risk or Emergency` : ""}. Highest level ${LABEL[m.severity]}.`;
  return `<g class="mk ${esc(m.severity)}" data-zone="${z}" role="button" tabindex="0" aria-label="${esc(label)}"><title>${esc(label)}</title>
    ${red ? `<circle class="ring" cx="${cx}" cy="${cy}" r="15" fill="none" stroke="${col}" stroke-width="2"/>` : ""}
    <circle cx="${cx}" cy="${cy}" r="${red ? 20 : 16}" fill="${col}" opacity=".18" filter="url(#glow)"/>
    <circle class="core" cx="${cx}" cy="${cy}" r="${red ? 14 : 12}" fill="${col}" filter="url(#glow)"/>
    <text x="${cx}" y="${cy + 4.5}" text-anchor="middle" font-family="Archivo,sans-serif" font-size="${red ? 13.5 : 12}" font-weight="800" fill="${m.severity === "warning" ? "#1A1400" : "#fff"}" pointer-events="none">${m.count}</text></g>`;
}

let lastNarrow = window.innerWidth < 720;
window.addEventListener("resize", () => { const n = window.innerWidth < 720; if (n !== lastNarrow && $("#bmap")) { lastNarrow = n; renderMap(); } });

/* ---------- contextual panel ---------- */
function renderCtx() {
  const el = $("#ctx");
  const all = sortIssues([...B.floors.flatMap((f) => f.issues), ...B.unassigned.issues]);
  if (!selFloor) {
    const sm = B.summary;
    el.innerHTML = `<div class="ctxhead"><div><span class="kicker">Selected: whole building</span><h2>${esc(roman(S.building))}</h2></div><span class="fstate fs-${esc(sm.building_state)}">${ICON[sm.building_state] || ""}${esc(sm.building_state_label)}</span></div>
      <p class="small muted" style="margin:0 0 8px">${sm.issues_active} active issue(s): ${sm.risk_count} fire-safety risk(s) and ${sm.equipment_active} equipment alert(s), each with its own rule level. Select a floor to see only its issues.</p>
      <div class="kicker" style="margin:6px 0">Most important issues</div>
      <div class="icards">${all.slice(0, 7).map((i) => icard(i)).join("") || '<div class="empty">No active issue in the current records.</div>'}</div>
      ${all.length > 7 ? `<p class="small muted" style="margin:8px 0 0">${all.length - 7} more: <a href="#/fire">Fire Safety Risks</a> · <a href="#/equipment">Equipment &amp; Systems</a></p>` : ""}`;
    bindIssues(el);
    return;
  }
  const f = B.floors.find((x) => x.zone === selFloor);
  const fr = f.issues.filter((i) => i.kind === "fire_risk").length, eq = f.issues.length - fr;
  const empty = f.state === "not_assessed" && !f.issue_count ? '<div class="insuff">Not Assessed: there are no records for this floor in the data, so its condition cannot be judged.</div>'
    : !f.issue_count ? `<div class="neutralbox">No active alert from ${f.records_checked} records checked for this floor. This is not a confirmation that the floor is safe: the data has no smoke, heat or gas sensors.</div>` : "";
  el.innerHTML = `<div class="ctxhead"><div><span class="kicker">Selected floor</span><h2>${esc(f.label)}</h2></div><span class="fstate fs-${esc(f.map_state)}">${ICON[f.map_state] || ""}${esc(f.map_state_label)}</span></div>
    ${empty}
    ${f.issue_count ? `<div class="icards">${sortIssues(f.issues).map((i) => icard(i, { noFloor: true })).join("")}</div>` : ""}
    <div class="ctxfacts"><span class="hchip">${fr} fire-safety risk(s)</span><span class="hchip">${eq} equipment alert(s)</span><span class="hchip">${f.records_checked} records checked</span>
      ${f.videos ? `<a class="hchip" href="#/media?floor=${esc(f.zone)}">${f.videos} survey video(s) · ${f.videos_analysed} analysed</a>` : '<span class="hchip">No survey video</span>'}</div>
    <p style="margin:12px 0 0"><button class="btn quiet" id="ctx-all">← Show the whole building</button></p>`;
  $("#ctx-all").onclick = () => { selFloor = null; renderMap(); renderCtx(); };
  bindIssues(el);
}

/* ---------- supporting panels ---------- */
function lvlBars(by) {
  const max = Math.max(1, ...Object.values(by || {}));
  return `<div class="lvlbars">${["emergency", "high", "warning", "watch"].map((s) => `<div class="lvlbar"><span>${esc(LABEL[s])}</span><span class="bar"><i style="width:${((by?.[s] || 0) / max) * 100}%;background:var(--${s})"></i></span><b class="num">${by?.[s] || 0}</b></div>`).join("")}</div>`;
}
function healthPanel(sm) {
  const eqs = B.floors.flatMap((f) => f.issues).concat(B.unassigned.issues).filter((i) => i.kind === "equipment");
  return `<div class="kicker">Equipment alerts by level (${sm.equipment_active})</div>${lvlBars(sm.equipment_by_level)}
    <div class="kicker">Fire-safety risks by level (${sm.risk_count})</div>${lvlBars(sm.risks_by_level)}
    <p class="small muted" style="margin:4px 0 0">${eqs.filter((i) => i.critical && i.open).length} critical item(s) with an open fault · ${eqs.filter((i) => i.subkind === "meter").length} meter(s) with unusual consumption · ${eqs.filter((i) => (i.fire_links || []).length).length} equipment alert(s) linked to a fire-safety risk</p>`;
}
function recentPanel(rec) {
  const rows = rec.records.slice(0, 6).map((e) => `<li><span class="when">${day(e.timestamp)} · ${esc(zshort(e.zone || "Building"))}</span>${tr(e, "title")} ${chip(e.evidence_id)}</li>`).join("");
  return `${rows ? `<ol class="tlc">${rows}</ol>` : '<div class="empty">No Data Available</div>'}
    <p class="small muted" style="margin:8px 0 0">${rec.videos.length ? `${rec.videos.length} survey video(s) analysed by Muse Spark, latest ${dt(rec.videos[0].analysed_at)}.` : "No survey video analysed yet."}</p>`;
}
function sourcesPanel() {
  const rows = S.sources.map((s) => `<div class="srcrow"><span class="dotst ${s.error ? "bad" : s.stale ? "bad" : ""}"></span><span>${esc(s.sheet_en || SRCNAME[s.source] || s.source)}<div class="tiny muted">${s.error ? "Not readable" : s.stale ? `Older than expected (${s.age_days} d)` : "Current"}</div></span><span class="tiny muted">${s.latest_record ? day(s.latest_record) : "—"}</span></div>`).join("");
  const sy = S.sync || {};
  return `${rows}
    <div class="srcrow"><span class="dotst ${sy.configured ? (sy.last && !sy.last.ok ? "bad" : "") : "off"}"></span><span>Google Drive sync<div class="tiny muted">${sy.configured ? (sy.auto_minutes ? `every ${sy.auto_minutes} min` : "manual") : "not connected"}</div></span><span class="tiny muted">${sy.last_ok_at ? dt(sy.last_ok_at) : "—"}</span></div>
    <div class="srcrow"><span class="dotst ${S.ai.configured ? "" : "off"}"></span><span>Muse Spark<div class="tiny muted">${S.ai.configured ? (S.ai.mode === "live" ? "live API" : "TEST endpoint") : "not configured"}</div></span><span class="tiny muted">${esc(S.ai.model || "")}</span></div>
    <p class="tiny muted" style="margin:8px 0 0">No smoke, heat or gas sensor feed is connected. Photos referenced in the logs: ${S.media.available} of ${S.media.references} available.</p>`;
}

/* ============================== Detail drawer for one issue ============================== */
const detailCache = {};
async function alertDetail(id) { return detailCache[id] || (detailCache[id] = await api(`/api/alerts/${encodeURIComponent(id)}`)); }
async function openIssue(i) {
  if (!i) return;
  openDrawer(i.kind === "fire_risk" ? "Fire-safety risk" : "Equipment alert", '<p class="muted">Loading…</p>');
  try {
    const br = (BR?.items || []).find((x) => x.issue_id === i.issue_id);
    if (i.kind === "fire_risk") {
      const d = await alertDetail(i.alert_id);
      $("#drawer-body").innerHTML = issueHead(i) + (br ? briefDl(br) : "") + riskDetailInline(d, i.signal_id);
    } else {
      const d = await api(`/api/equipment-alerts/${encodeURIComponent(i.alert_id)}`);
      $("#drawer-body").innerHTML = issueHead(i) + eqDetailInline(d);
    }
    bindEvidence();
  } catch (e) { $("#drawer-body").innerHTML = `<div class="errbox">Could not load the details: ${esc(e.message)}</div>`; }
}
function issueHead(i) {
  return `<div class="rc-top">${lvl(i.severity)}<span class="kindtag ${esc(i.kind)}">${esc(i.kind_label)}</span>${i.kind === "fire_risk" ? riskStatus(i) : i.open ? '<span class="rst open">Open fault</span>' : ""}</div>
    <h3 style="margin:8px 0 2px;font-size:18px">${esc(i.kind === "fire_risk" ? i.title : `${issueName(i)}: ${issueDesc(i)}`)}</h3>
    <dl class="dsum"><dt>Location</dt><dd>${esc(i.zone_label || zshort(i.zone))}${i.place && i.kind === "fire_risk" ? ` · ${esc(i.place)}` : ""}</dd><dt>Rule level</dt><dd>${esc(LABEL[i.severity])} <span class="muted small">(rule result; AI never changes it)</span></dd><dt>Evidence</dt><dd>${esc(i.count_text || "—")}</dd></dl>`;
}
function briefDl(b) {
  const rows = [["Observed", b.observed], ["Why it matters", b.why_it_matters], ["Potential consequence", b.potential_consequence], ["Not established", b.uncertainty], ["First action", b.first_action]].filter(([, f]) => f?.text);
  return `<h5>Summary · <span class="aist ${esc(b.ai.code)}">${esc(b.ai.label)}</span></h5><dl class="dsum">${rows.map(([k, f]) => `<dt>${k}</dt><dd>${fieldTxt(f)}</dd>`).join("")}</dl>`;
}
function riskDetailInline(d, signalId) {
  const s = d.signals.find((x) => x.signal_id === signalId) || d.signals[0];
  const recs = d.evidence.filter((e) => s.evidence_ids.includes(e.evidence_id));
  return `<h5>Source records</h5>${recs.map((e) => `<div class="small rrow"><span class="when">${day(e.timestamp)}</span><span>${tr(e, "title")} ${e.is_open ? '<span class="open">● unresolved</span>' : ""}<div class="muted">${org(e.origin)}${esc(e.source?.sheet_en || "")}${e.source?.row ? ` · row ${e.source.row}` : ""} · status: ${tr(e, "status") || "—"} ${chip(e.evidence_id)}</div></span></div>`).join("") || '<p class="muted small">No Data Available</p>'}
    <h5>Possible chain of events</h5><ol class="chain">${s.fields.risk_chain.map((c) => `<li>${esc(c)}</li>`).join("")}</ol><p class="small muted">${org("rule")}A possible chain of events, not a prediction.</p>
    <h5>Recommended actions</h5><ul class="actions">${s.fields.preventive_actions.map((a, n) => `<li><span class="box" aria-hidden="true"></span><span>${n === 0 ? "<b>First:</b> " : ""}${esc(a)}</span></li>`).join("")}</ul>
    <p class="small"><b>Close when:</b> ${esc(s.fields.closure_condition || "—")}</p>
    ${d.related_equipment.length ? `<h5>Related equipment alerts</h5>${d.related_equipment.map((x) => `<a class="mini" href="#/equipment/${encodeURIComponent(x.alert_id)}">${lvl(x.severity)}<span>${esc(nm(x.asset_name, x.asset_name_en, x.asset_id || "Equipment"))}<br><span class="small muted">Why linked: ${x.reasons.map((r) => esc(roman(r))).join("; ")}</span></span></a>`).join("")}` : ""}
    ${d.survey_videos.length ? `<h5>Survey videos of this zone · Muse Spark observations</h5>${videoContext(d.survey_videos, true)}` : ""}
    <h5>AI analysis</h5>${aiFull(d, s.signal_id)}`;
}
function eqDetailInline(d) {
  const F = d.fields;
  return `<h5>Problem</h5><ul class="small">${F.why_short.map((w) => `<li>${org("rule")}${esc(w)}</li>`).join("")}</ul>
    <h5>Consequence if not handled</h5><p class="small">${esc(F.consequence)}</p><ol class="chain">${F.risk_chain.map((c) => `<li>${esc(c)}</li>`).join("")}</ol>
    <h5>Possible causes</h5><p class="small"><b>${esc(F.cause_status)}</b></p>${F.possible_causes.length ? `<ul class="small">${F.possible_causes.map((c) => `<li>${esc(c.cause)}</li>`).join("")}</ul>` : ""}
    <h5>Actions · act ${esc(F.deadline.text)}</h5><ul class="actions">${F.preventive_actions.map((x) => `<li><span class="box" aria-hidden="true"></span><span>${esc(x)}</span></li>`).join("")}</ul>
    <h5>Evidence (${F.evidence.length})</h5>${F.evidence.slice(0, 8).map((e) => `<div class="small rrow"><span class="when">${day(e.time)}</span><span>${tr(e, "title")}${e.unresolved ? '<span class="open">● open</span>' : ""} ${chip(e.evidence_id)}</span></div>`).join("")}
    ${d.fire_alerts.length ? `<h5>Linked fire-safety risk</h5>${d.fire_alerts.map((x) => `<a class="mini" href="#/fire/${esc(x.alert_id)}">${lvl(x.severity)}<span>${esc(x.zone_label)}<br><span class="small muted">Why linked: ${x.reasons.map((r) => esc(roman(r))).join("; ")}</span></span></a>`).join("")}` : '<p class="small muted">Not part of any fire-safety risk. Not every equipment fault is a fire risk.</p>'}
    <p style="margin-top:12px"><a href="#/equipment/${encodeURIComponent(d.alert.alert_id)}">Open the equipment alert page →</a></p>`;
}

/* ============================== Fire Safety Risks ============================== */
async function viewFireList() {
  const alerts = await api("/api/fire-alerts");
  const risks = alerts.flatMap((a) => (a.risks || []).map((r) => fireIssue(r, a)));
  const zones = [...new Set(risks.map((r) => r.zone_label))], types = [...new Set(risks.map((r) => r.risk_type))];
  $("#app").innerHTML = `<div class="pagehead"><div><span class="kicker">Specialised view</span><h1>Fire Safety Risks</h1>
      <p class="muted">Each card is one fire-safety risk found by the rule set. Risks of the same zone form one investigation with shared evidence and one Muse Spark analysis. These are potential risks, not confirmed fires.</p></div>
      <div class="small">${alerts.map((a) => `<a class="hchip" href="#/fire/${esc(a.alert_id)}">${esc(a.zone_label)} · ${esc(LABEL[a.severity])} · full investigation →</a>`).join(" ")}</div></div>
    <div class="filters" role="group" aria-label="Filters">
      <select id="fs" aria-label="Severity"><option value="">All levels</option>${["emergency", "high", "warning", "watch"].map((s) => `<option value="${s}">${esc(LABEL[s])} and above</option>`).join("")}</select>
      <select id="fz" aria-label="Floor or zone"><option value="">All floors</option>${zones.map((z) => `<option>${esc(z)}</option>`).join("")}</select>
      <select id="fo" aria-label="Status"><option value="">Any status</option><option value="open">Unresolved records</option><option value="fixed">Marked fixed in records</option>${Object.entries(STATUS_TXT).map(([k, v]) => `<option value="v:${k}">Alert: ${esc(v)}</option>`).join("")}</select>
      <select id="ft" aria-label="Risk type"><option value="">All risk types</option>${types.map((t) => `<option value="${esc(t)}">${esc(RTYPE[t] || t)}</option>`).join("")}</select>
      <span class="small muted" id="fc"></span></div><div id="rows" class="icards grid"></div>`;
  const render = () => {
    const sv = $("#fs").value, z = $("#fz").value, o = $("#fo").value, t = $("#ft").value;
    const list = sortIssues(risks.filter((r) => (!sv || rank(r.severity) >= rank(sv)) && (!z || r.zone_label === z) && (!t || r.risk_type === t)
      && (!o || (o === "open" ? r.open : o === "fixed" ? !r.open : (r.verification?.status || "new") === o.slice(2)))));
    $("#fc").textContent = `${list.length} of ${risks.length} risks`;
    $("#rows").innerHTML = list.map((r) => icard(r)).join("") || '<div class="empty">No risk matches these filters.</div>';
    bindIssues($("#rows"));
  };
  ["#fs", "#fz", "#fo", "#ft"].forEach((s) => $(s).addEventListener("change", render));
  render();
}

/* ============================== Equipment & Systems ============================== */
async function viewEquipList() {
  const rows = await api("/api/equipment-alerts");
  const items = rows.map((a) => ({ ...eqIssue(a), _a: a }));
  const act = items.filter((i) => isActive(i._a));
  const by = {}; act.forEach((i) => (by[i.severity] = (by[i.severity] || 0) + 1));
  const zones = [...new Set(rows.map((a) => a.zone_label))];
  $("#app").innerHTML = `<div class="pagehead"><div><span class="kicker">Specialised view</span><h1>Equipment &amp; Systems</h1>
      <p class="muted">Equipment faults, overdue repairs, repeated faults and meter consumption findings, from the rules of the earlier risk-alert skill. Their levels are not changed by the fire-risk module; some are linked to a fire-safety risk with a stated reason.</p></div></div>
    <section class="health" aria-label="System health">
      <div class="kpi"><span class="kicker">Active equipment alerts</span><span class="v num">${act.length}</span><span class="d">${["emergency", "high", "warning", "watch"].filter((s) => by[s]).map((s) => `${by[s]} ${LABEL[s]}`).join(" · ") || "none"}</span></div>
      <div class="kpi k-high"><span class="kicker">Critical, open fault</span><span class="v num">${act.filter((i) => i.critical && i.open).length}</span><span class="d">critical equipment with an open record</span></div>
      <div class="kpi"><span class="kicker">Technical faults</span><span class="v num">${act.filter((i) => i.subkind !== "meter").length}</span><span class="d">open, overdue or repeated</span></div>
      <div class="kpi"><span class="kicker">Consumption anomalies</span><span class="v num">${act.filter((i) => i.subkind === "meter").length}</span><span class="d">meters with unusual periods</span></div>
      <div class="kpi"><span class="kicker">Linked to fire safety</span><span class="v num">${act.filter((i) => i.fire_links.length).length}</span><span class="d">with a stated reason</span></div>
    </section>
    <div class="filters" role="group" aria-label="Filters">
      ${[["all", "All levels"], ["warning", "Warning and above"]].map(([k, t], i) => `<button class="chipbtn" data-f="${k}" aria-pressed="${i === 0}">${t}</button>`).join("")}
      <select id="et" aria-label="Type"><option value="">All types</option><option value="equipment">Technical (faults)</option><option value="meter">Consumption (meters)</option></select>
      <select id="ez" aria-label="Zone"><option value="">All zones</option>${zones.map((z) => `<option>${esc(z)}</option>`).join("")}</select>
      <label class="small muted"><input type="checkbox" id="ec"> Critical equipment only</label>
      <label class="small muted"><input type="checkbox" id="hide-res" checked> Hide resolved</label>
      <input type="text" id="eq" placeholder="Search equipment" style="width:200px">
      <span class="small muted" id="ecount"></span></div><div id="rows" class="icards grid"></div>`;
  let f = "all";
  const render = () => {
    const t = $("#et").value, z = $("#ez").value, c = $("#ec").checked, hide = $("#hide-res").checked, q = $("#eq").value.toLowerCase();
    const list = sortIssues(items.filter((i) => (f === "all" || rank(i.severity) >= rank(f)) && (!t || i._a.type === t) && (!z || i._a.zone_label === z) && (!c || i.critical) && !(hide && !isActive(i._a))
      && (!q || `${issueName(i)} ${i._a.asset_id || ""} ${i.summary || ""}`.toLowerCase().includes(q))));
    $("#ecount").textContent = `${list.length} of ${items.length}`;
    $("#rows").innerHTML = list.map((i) => icard(i)).join("") || '<div class="empty">No equipment alert matches these filters.</div>';
    bindIssues($("#rows"));
  };
  $$(".chipbtn").forEach((b) => b.addEventListener("click", () => { f = b.dataset.f; $$(".chipbtn").forEach((x) => x.setAttribute("aria-pressed", x === b)); render(); }));
  ["#et", "#ez", "#ec", "#hide-res"].forEach((s) => $(s).addEventListener("change", render));
  $("#eq").addEventListener("input", render);
  render();
}

const DATA_TABS = (on) => `<div class="pagehead"><div><span class="kicker">Specialised view</span><h1>Data &amp; Evidence</h1></div></div>
  <nav class="subnav" aria-label="Data and evidence sections"><a href="#/data" class="${on === "sources" ? "on" : ""}">Sources &amp; Sync</a><a href="#/media" class="${on === "media" ? "on" : ""}">Photos &amp; Videos</a></nav>`;
/* ============================== Fire-risk alert detail (6 sections) ============================== */
let aiPoll = null;
async function viewFire(id, focusRisk) {
  clearInterval(aiPoll);
  delete detailCache[id];
  const d = await alertDetail(id);
  const a = d.alert, F = d.fields, st = d.ai_status;
  const inv = d.investigation, r = inv && inv.status === "ok" ? inv.result : null;
  const aiTag = inv && inv.api_mode === "test" ? org("test", "TEST · mock API") : org("ai");
  const ids = (l) => (l || []).map(chip).join("") || '<span class="muted small">none</span>';
  const insufficient = F.assessment_class === "insufficient_evidence";
  const sigById = Object.fromEntries(d.signals.map((s) => [s.signal_id, s]));
  const risks = F.risks || [];
  const evRow = (e) => {
    const v = e.values || {};
    let val = "";
    if (e.kind === "meter_episode") val = `${fmtNum(v.peak)} <small>vs median ${fmtNum(v.median)} ${esc(v.unit || "")}${v.unit_verified ? "" : " (unit unverified)"}</small>`;
    else if (e.kind === "generator_run" && v.minutes != null) val = `${v.minutes} min`;
    return `<div class="evi"><span class="when">${day(e.timestamp)}</span>
      <span><span class="what">${tr(e, "title")}</span>${e.is_open ? '<span class="open">● unresolved</span>' : ""}
        <div class="src">${org(e.origin)}${esc(KIND[e.kind] || e.kind)} · ${esc(e.source?.sheet_en || "")}${e.source?.row ? ` · row ${e.source.row}` : ""} ${chip(e.evidence_id)}</div>
        ${e.status ? `<div class="src">Status in source: ${tr(e, "status")}</div>` : ""}</span><span class="val">${val}</span></div>`;
  };
  const findings = d.evidence.filter((e) => e.role === "finding" && e.kind !== "meter_episode")
    .sort((x, y) => (y.is_open === true) - (x.is_open === true) || (y.timestamp || "").localeCompare(x.timestamp || ""));
  const context = d.evidence.filter((e) => e.role === "context");
  const sec = (n, title, body) => `<section class="q" id="s${n}"><h2><span class="qn">${n}</span>${title}</h2>${body}</section>`;

  const s1 = `${risks.map((c) => `<div class="det-risk ${c.signal_id === focusRisk ? "focus" : ""}" id="r-${esc(c.signal_id)}">
      <div class="rc-top">${lvl(c.severity)}<span class="rc-loc">${esc(c.location)}</span>${riskStatus(c)}</div>
      <h4>${esc(c.risk)}</h4><p class="small muted">First record ${day(c.first_seen)} · latest ${day(c.last_seen)} · ${esc(c.evidence)} · ${c.origin === "PORTED" ? "rule from the earlier skill" : "new rule"} ${esc(c.rule_id)}</p></div>`).join("")}
    <p style="margin:10px 0 0">Equipment and rooms: ${F.affected_assets.map(([eid, name]) => `<button class="asset" data-asset="${esc(eid)}"><b>${esc(nm(name, null, eid))}</b><span class="muted small">${esc(eid)}</span></button>`).join("") || '<span class="muted">No equipment code in the records.</span>'}</p>
    ${insufficient ? '<div class="insuff">Not enough evidence to confirm. The records are signals, not a confirmed hazard.</div>' : `<p class="small muted">${org("rule")}${esc(F.assessment_text)}. No fire has been reported in these records.</p>`}`;

  const s2 = `${risks.map((c) => { const s = sigById[c.signal_id]; return `<div class="whyblock"><h4>${esc(c.risk)}</h4><p>${esc(c.why_it_matters)}</p>
      <ol class="chain">${s.fields.risk_chain.map((x) => `<li>${esc(x)}</li>`).join("")}</ol>
      <p class="small muted">${org("rule")}Possible chain of events, not a prediction. Condition: ${esc(s.fields.trigger_condition)} Consequence if not handled: ${esc(s.fields.consequence)}</p>
      ${s.fields.possible_causes?.length ? `<details><summary>Possible causes listed by the rules (not verified)</summary><ul class="small">${s.fields.possible_causes.map((pc) => `<li>${esc(pc.cause)} <span class="muted">(${basisTxt(pc.basis)})</span></li>`).join("")}</ul></details>` : ""}</div>`; }).join("")}
    <p class="small"><b>Not verified:</b> ${F.unknowns.slice(0, 4).map(esc).join(" · ")}${F.unknowns.length > 4 ? ` · <a href="javascript:void(0)" data-jump="s4">more</a>` : ""}</p>`;

  const s3 = `<h3 class="sub">Source records (${findings.length})</h3>${findings.slice(0, 6).map(evRow).join("") || '<div class="empty">No Data Available</div>'}
    ${findings.length > 6 ? `<details><summary>${findings.length - 6} more records</summary>${findings.slice(6).map(evRow).join("")}</details>` : ""}
    ${d.trends.length ? `<h3 class="sub" style="margin-top:14px">Meter readings around each anomaly</h3><p class="small muted">${org("derived")}Daily consumption from real readings, 7 days before and after.</p>${d.trends.slice(0, 2).map(trendChart).join("")}` : ""}
    <h3 class="sub" style="margin-top:14px">Survey videos of this zone (${d.survey_videos.length})</h3>${videoContext(d.survey_videos)}
    ${d.survey_video_refs?.length ? `<p class="small">${d.survey_video_refs.length} more video(s) of this zone are listed on Drive but not on this computer yet. <a href="#/media">See status</a>.</p>` : ""}
    <h3 class="sub" style="margin-top:14px">Linked equipment alerts (${d.related_equipment.length})</h3>
    ${d.related_equipment.map((x) => `<a class="mini" href="#/equipment/${encodeURIComponent(x.alert_id)}">${lvl(x.severity)}<span><b>${esc(nm(x.asset_name, x.asset_name_en, "Equipment (name translation pending)"))}</b> · ${esc(nm(x.headline, x.headline_en, "Equipment alert"))}<br><span class="small muted">${org("rule")}Why linked: ${x.reasons.map((r) => esc(roman(r))).join("; ")}</span></span></a>`).join("") || '<p class="muted small">No equipment alert is linked to this risk.</p>'}
    ${context.length ? `<details><summary>Records that may weaken the alert (${context.length})</summary><p class="small muted">Latest daily checklists and scheduled generator runs. A passed checklist does not prove the issue is gone.</p>${context.map(evRow).join("")}</details>` : ""}
    ${d.maintenance_history.length ? `<details><summary>Inspection and maintenance records of the equipment (${d.maintenance_history.length})</summary>${d.maintenance_history.map(evRow).join("")}</details>` : ""}`;

  const s4 = `<div class="aihead">${aiTag}${aiPill(st, true)}<button class="btn ai" id="ai-run" ${st.configured && st.code !== "running" ? "" : "disabled"}>${st.code === "running" ? "Analysing…" : r ? "Re-analyse with Muse Spark" : "Analyse with Muse Spark"}</button></div>
    ${!st.configured ? '<div class="warnbox">Muse Spark is not configured on this computer. The rule-based explanation is shown in the other sections.</div>' : ""}
    ${st.code === "failed" ? `<div class="errbox">AI Analysis Failed — ${esc(st.error?.kind || "")}: ${esc(st.error?.message || "")}. The alert, its severity and the rule explanation are unaffected.</div>` : ""}
    ${r && !st.result_is_current ? `<div class="warnbox">This analysis (${dt(inv.created_at)}) was made on older evidence.${st.code === "running" ? " A new analysis is running." : ""}</div>` : ""}
    ${r ? `<div class="aibox"><div class="small muted">${esc(inv.model)} · ${dt(inv.created_at)} · ${esc(inv.seconds)} s · ${esc(inv.trigger === "auto" ? "automatic" : "on request")}</div>
      ${inv.validation?.ok === false ? `<div class="warnbox">${inv.validation.invalid_evidence_ids?.length ? `Removed ${inv.validation.invalid_evidence_ids.length} citation(s) to records that do not exist. ` : ""}${inv.validation.unsupported_facts?.length ? `${inv.validation.unsupported_facts.length} statement(s) without a valid source are marked unsupported.` : ""}</div>` : ""}
      <h3 class="sub">AI interpretation</h3><p>${aiT(r.situation || r.summary)}</p>
      <p class="small">AI priority ${lvl(r.risk_assessment.ai_priority)} · official rule severity ${lvl(a.severity)} — ${r.risk_assessment.agrees_with_rule_severity ? "agrees" : "differs; the rule severity stays"}. ${aiT(r.risk_assessment.rationale)}</p>
      <details open><summary>Confirmed observations the AI read from the records (${r.observed_facts.length})</summary><ul class="small">${r.observed_facts.map((f) => `<li>${aiT(f.statement)} ${f.supported === false ? '<b style="color:var(--emergency)">unsupported</b>' : ""} ${ids(f.evidence_ids)}</li>`).join("")}</ul></details>
      ${r.hypotheses?.length ? `<details><summary>Possible causes — hypotheses, not confirmed (${r.hypotheses.length})</summary>${r.hypotheses.map((h) => `<div class="hyp"><span class="plaus">${esc(h.plausibility)}</span> <b>${aiT(h.cause)}</b><div class="small">${aiT(h.reasoning)}</div><div class="small muted">Supports: ${ids(h.supporting_evidence_ids)} Contradicts: ${ids(h.contradicting_evidence_ids)}</div><div class="small"><i>How to verify:</i> ${aiT(h.how_to_verify)}</div></div>`).join("")}</details>` : ""}
      ${r.scenarios?.length ? `<details><summary>Possible scenarios — not predictions (${r.scenarios.length})</summary>${r.scenarios.map((sc) => `<div class="scen"><b>${aiT(sc.scenario)}</b> <span class="plaus">${esc(sc.plausibility)}</span><div class="small">${aiT(sc.how_it_could_develop)}</div><div class="small"><span class="pro">Supports</span> ${ids(sc.supporting_evidence_ids)} <span class="con">Weakens</span> ${ids(sc.weakening_evidence_ids)}</div><div class="small"><i>Would confirm:</i> ${aiT(sc.what_would_confirm)}</div></div>`).join("")}</details>` : ""}
      <details><summary>Missing information and limits of the analysis</summary><ul class="unk">${(r.missing_information || []).map((m) => `<li><b>${aiT(m.item)}</b> — ${aiT(m.why_it_matters)}</li>`).join("")}${(r.limitations || []).map((x) => `<li>${aiT(x)}</li>`).join("")}</ul><p class="small"><b>Uncertainty:</b> ${aiT(r.uncertainty)}</p></details></div>`
      : st.code === "running" ? '<p class="muted">Muse Spark is reading the evidence. The rule-based sections are already complete.</p>' : '<p class="muted">Not Analysed by AI yet. The rule-based explanation applies.</p>'}
    <h3 class="sub" style="margin-top:14px">Not verified (rule set)</h3><ul class="unk">${F.unknowns.map((u) => `<li>${esc(u)}</li>`).join("")}${d.data_quality.length ? `<li>${d.data_quality.length} data issue(s) in these records</li>` : ""}</ul>`;

  const s5 = `<p class="small muted" style="margin:-4px 0 8px">${org("rule")}Deadline <b>${esc(F.deadline.text)}</b> (${esc(F.deadline.basis)}). Guidance is preliminary and has not been reviewed by a certified fire-safety expert. If water is in contact with energised equipment, or there is any sign of fire or smoke, follow the building's emergency procedure.</p>
    ${risks.map((c) => { const s = sigById[c.signal_id]; return `<div class="actgroup"><h4>${lvl(c.severity)} ${esc(c.risk)}</h4><ul class="actions">${s.fields.preventive_actions.map((x, i) => `<li><span class="box" aria-hidden="true"></span><span>${i === 0 ? "<b>First:</b> " : ""}${esc(x)}</span></li>`).join("")}</ul><p class="small"><b>Close when:</b> ${esc(s.fields.closure_condition)}</p></div>`; }).join("")}
    ${r?.recommended_actions?.length ? `<h3 class="sub" style="margin-top:12px">${aiTag}Additional checks suggested by Muse Spark</h3><ul class="actions">${r.recommended_actions.map((x) => `<li><span class="box" aria-hidden="true"></span><span><b>${esc((x.urgency || "").replace(/_/g, " "))}</b> — ${aiT(x.action)} <span class="muted small">(${aiT(x.responsible_role)})</span><br><span class="small muted">${aiT(x.reason)}</span> ${ids(x.evidence_ids)}</span></li>`).join("")}</ul>` : ""}`;

  const s6 = `<div class="hist2"><div><h3 class="sub">Status changes</h3>${d.status_log.map((x) => `<div class="small">${dt(x.changed_at)} — ${esc(STATUS_TXT[x.status] || x.status)}${x.note ? `: ${esc(x.note)}` : ""}${x.changed_by ? ` (${esc(x.changed_by)})` : ""}</div>`).join("") || '<span class="muted small">No status change yet.</span>'}</div>
    <div><h3 class="sub">Severity per analysis run</h3>${d.history.slice(0, 8).map((h) => `<div class="small">${dt(h.recorded_at)} ${lvl(h.severity)} <span class="muted">${h.open_items} open</span></div>`).join("") || '<span class="muted small">First run.</span>'}</div>
    <div><h3 class="sub">AI analyses</h3>${d.investigations.slice(0, 8).map((x) => `<div class="small">${dt(x.created_at)} — ${esc(x.status === "ok" ? "completed" : x.status)}</div>`).join("") || '<span class="muted small">None yet.</span>'}</div></div>
    <h3 class="sub" style="margin-top:12px">Timeline of the records</h3><ol class="tline">${d.timeline.filter((e) => e.role === "finding").slice(-14).map((e) => `<li><span class="when">${day(e.timestamp)}</span> ${tr(e, "title")}${e.is_open ? '<span class="open">● unresolved</span>' : ""} ${chip(e.evidence_id)}</li>`).join("") || "<li class='muted'>No Data Available</li>"}</ol>`;

  $("#app").innerHTML = `<div class="crumbs"><a href="#/fire">Fire Safety Risks</a> / ${esc(a.alert_id)}</div>
    <div class="dhead">${lvl(a.severity, true)}<h1>${esc(a.zone_label)}</h1><span class="aist rulefb">Status: ${stat(d.summary)}</span>${aiPill(st)}</div>
    <nav class="toc" aria-label="Sections">${["What Was Detected", "Why This Matters", "Supporting Evidence", "AI Analysis", "Recommended Actions", "History"].map((t, i) => `<a href="javascript:void(0)" data-jump="s${i + 1}">${i + 1}. ${t}</a>`).join("")}</nav>
    <div class="layout"><div>${sec(1, "What Was Detected", s1)}${sec(2, "Why This Matters", s2)}${sec(3, "Supporting Evidence", s3)}${sec(4, "AI Analysis", s4)}${sec(5, "Recommended Actions", s5)}${sec(6, "History", s6)}</div>
    <aside class="side"><section class="q"><h2>Severity and urgency</h2>
      <dl class="kv"><dt>Severity</dt><dd>${lvl(a.severity)} <span class="small muted">(rule)</span></dd><dt>Status</dt><dd>${stat(d.summary)}</dd><dt>Urgency</dt><dd>${esc(F.urgency.label)}</dd><dt>Act</dt><dd><b>${esc(F.deadline.text)}</b></dd>
      <dt>Confidence</dt><dd>${esc(F.confidence.level)} <span class="muted small">— ${esc(F.confidence.reason)}</span></dd><dt>Detected</dt><dd>${dt(d.summary.detected_at)}</dd><dt>Latest record</dt><dd>${day(a.last_seen)}</dd><dt>AI</dt><dd>${aiPill(st)}</dd></dl></section>
      <section class="q"><h2>Verification</h2>${verifyBox(d)}</section></aside></div>`;
  $$("[data-jump]").forEach((el) => (el.onclick = () => document.getElementById(el.dataset.jump).scrollIntoView({ behavior: "smooth" })));
  bindEvidence(); bindAssets(); bindVerify(a.alert_id);
  if (focusRisk) setTimeout(() => document.getElementById(`r-${focusRisk}`)?.scrollIntoView({ block: "center" }), 50);
  const b = $("#ai-run");
  if (b) b.onclick = async () => {
    b.disabled = true; b.textContent = "Queued…";
    try { await api(`/api/alerts/${encodeURIComponent(id)}/investigate`, { method: "POST" }); } catch (e) { alertBar("The AI request failed: " + e.message); }
    viewFire(id, focusRisk);
  };
  if (st.code === "running") aiPoll = setInterval(async () => {
    if (!location.hash.startsWith("#/fire/")) return clearInterval(aiPoll);
    const n = await api(`/api/alerts/${encodeURIComponent(id)}/ai-status`).catch(() => null);
    if (n && n.code !== "running") { clearInterval(aiPoll); viewFire(id, focusRisk); }
  }, 5000);
}

function videoContext(vs, open) {
  if (!vs.length) return '<p class="muted small">Evidence Unavailable: no survey video of this zone on this computer.</p>';
  return vs.map((v) => `<div class="vctx"><a href="#/video/${esc(v.video_id)}"><b>${esc(v.filename)}</b></a> <span class="muted small">${esc([plain(v, "floor"), plain(v, "area"), plain(v, "room")].filter(Boolean).join(" / "))}</span>
    <div class="small muted" style="margin:4px 0">${esc(v.recording_note)}</div>
    ${v.observations.length ? `<details${open ? " open" : ""}><summary class="small">${org("ai_vision")}${v.observations.length} observations by Muse Spark (${dt(v.analysis_created_at)})</summary><p class="small muted" style="margin:4px 0">Approximate times — check the clip.</p><ul class="small">${v.observations.map((o) => `<li><a href="#/video/${esc(v.video_id)}?t=${o.time_start_s}">${fmtTime(o.time_start_s)}</a> ${esc(o.category.replace(/_/g, " "))}: ${aiT(o.observation)} <span class="muted">(${esc(o.visible_certainty.replace(/_/g, " "))})</span></li>`).join("")}</ul></details>`
      : `<p class="small muted" style="margin:0">Not analysed by Muse Spark yet.</p>`}</div>`).join("");
}

function eqRow(a) {
  return `<a class="arow eq ${esc(a.severity)}" href="#/equipment/${encodeURIComponent(a.alert_id)}">
    <span>${lvl(a.severity)}<div class="stat" style="margin-top:6px">${stat(a)}</div></span>
    <span><span class="t">${esc(nm(a.asset_name, a.asset_name_en, a.asset_id || "Equipment"))}</span>${a.critical ? ' <span class="crit">critical equipment</span>' : ""}<div class="why">${esc(nm(a.headline, a.headline_en, a.why))}</div>
      <div class="muted small">${esc(a.asset_id || "no equipment code")} · ${esc(a.zone_label)} · ${a.type === "meter" ? "consumption" : "technical"}${a.fire_links.length ? ` · <b>linked to a fire-safety risk (${a.fire_links.map((l) => esc(l.fire_alert_id)).join(", ")})</b>` : ""}</div></span>
    <span class="stat c3">Detected <b>${day(a.detected_at)}</b><br>Latest record <b>${day(a.last_seen)}</b></span>
    <span class="stat c4">Act <b>${esc(a.deadline?.text || "—")}</b><br>${a.open_items} open</span></a>`;
}
/* ============================== Photos & Videos gallery ============================== */
async function viewMedia(query) {
  const [m, vids, bld] = await Promise.all([api("/api/media"), api("/api/videos"), api("/api/building")]);
  const q = new URLSearchParams(query || "");
  const alertZones = new Set(bld.floors.filter((f) => f.risk_count).map((f) => f.zone));
  const floors = [...new Set(vids.videos.map((v) => v.zone || ""))];
  const zoneOpts = Object.entries(vids.zones).map(([k, v]) => `<option value="${esc(k)}">${esc(v)}</option>`).join("");
  $("#app").innerHTML = `${DATA_TABS("media")}
    <p class="muted">Real evidence from the building. A survey video shows what was visible <b>when it was recorded</b>; it never changes a rule severity and does not prove that equipment works today.</p>
    <div class="filters" role="group" aria-label="Filters">
      <select id="gf" aria-label="Floor"><option value="">All floors</option>${floors.map((z) => `<option value="${esc(z)}" ${q.get("floor") === z ? "selected" : ""}>${esc(vids.zones[z] || "Not assigned")}</option>`).join("")}</select>
      <select id="ga" aria-label="Linked alert"><option value="">With or without fire-safety risk</option><option value="yes">Floor has an active fire-safety risk</option></select>
      <input type="date" id="gd" aria-label="Recorded on" title="Recorded on">
      <input type="text" id="gq" placeholder="Search name, room or equipment" style="width:240px">
      <span class="small muted" id="gc"></span></div>
    <div id="gallery" class="gallery"></div>
    <section class="panel" style="margin-top:18px"><h2>Google Drive</h2>${driveVideos(vids)}
      <details style="margin-top:14px"><summary>Other ways to add a video</summary>
        <p class="small muted">Put downloaded files in <b>${esc(vids.inbox)}</b> and press <button class="btn" id="vimport">Import from folder</button> <span class="small muted" id="vimsg"></span>, or upload one file below.</p>
        <form id="vform" class="vform">
          <label>Video file (.mp4) <input type="file" id="vfile" accept="video/mp4,video/quicktime,.mp4,.mov,.m4v" required></label>
          <label>Floor <select id="vzone"><option value="">Not assigned</option>${zoneOpts}</select></label>
          <label>Floor name <input id="vfloor" placeholder="e.g. Basement 1"></label>
          <label>Area <input id="varea" placeholder="e.g. technical corridor"></label>
          <label>Room <input id="vroom" placeholder="e.g. MSB room"></label>
          <label>Recorded on <input type="datetime-local" id="vwhen"></label>
          <label class="wide">Note <input id="vnote2" placeholder="optional"></label>
          <button class="btn primary" type="submit">Upload</button><span class="small muted" id="vmsg2"></span>
        </form></details></section>
    <section class="panel" style="margin-top:16px"><h2>Photos referenced in the logs</h2>
      <p class="small muted" style="margin:0">${m.summary.references} photo references found in the records; ${m.summary.available} files available on this computer. Evidence Unavailable until the photo files are connected; files placed in <b>${esc(m.summary.media_dir)}</b> are matched to their records by name.</p></section>`;
  const render = () => {
    const f = $("#gf").value, al = $("#ga").value, d = $("#gd").value, s = $("#gq").value.toLowerCase();
    const list = vids.videos.filter((v) => (!f || (v.zone || "") === f) && (!al || alertZones.has(v.zone)) && (!d || (v.recorded_at || "").slice(0, 10) === d)
      && (!s || `${v.filename} ${v.room || ""} ${v.area || ""} ${(v.equipment || []).map((e) => `${e.name || ""} ${e.equipment_id}`).join(" ")}`.toLowerCase().includes(s)));
    $("#gc").textContent = `${list.length} of ${vids.videos.length} videos`;
    $("#gallery").innerHTML = list.map((v) => `<a class="gcard" href="#/video/${esc(v.video_id)}">
      <video preload="metadata" muted src="/api/videos/${encodeURIComponent(v.video_id)}/file#t=2" aria-hidden="true"></video>
      <div class="gbody"><b>${esc(v.filename)}</b><div class="small muted">${esc(v.zone_label)}${v.room ? " · " + tr(v, "room") : ""}</div>
        <div class="small">${v.recorded_at ? `Recorded ${dt(v.recorded_at)}${v.recorded_at_source === "mp4_metadata" ? " (camera clock)" : ""}` : "Recording date unknown"}${v.duration_s ? ` · ${fmtTime(v.duration_s)}` : ""}</div>
        <div class="small">${v.analysis_status === "ok" ? `${org("ai_vision")}Analysed by Muse Spark` : esc(VSTAT[v.analysis_status] || v.analysis_status)}${alertZones.has(v.zone) ? ' · <span class="rst open">floor has a fire-safety risk</span>' : ""}</div>
        <div class="small muted">${v.drive_file_id ? `${org("source")}Google Drive${v.equipment?.length ? ` · Asset register: ${v.equipment.map((e) => esc(e.equipment_id)).join(", ")}` : ""}` : "Uploaded on this computer"}</div></div></a>`).join("") || '<div class="empty">No video matches these filters.</div>';
  };
  ["#gf", "#ga", "#gd"].forEach((x) => $(x).addEventListener("change", render)); $("#gq").addEventListener("input", render);
  render();
  bindMediaForms(vids);
}
function bindMediaForms(vids) {
  const dsb = $("#vdrive");
  if (dsb) dsb.onclick = async () => { dsb.disabled = true; try { await api("/api/videos/drive-sync", { method: "POST" }); } catch (e) { alertBar("Could not start: " + e.message); } viewMedia(); };
  clearInterval(vidPoll);
  if (vids.drive_sync.progress?.running) vidPoll = setInterval(async () => {
    if (!location.hash.startsWith("#/media")) return clearInterval(vidPoll);
    const n = await api("/api/videos").catch(() => null);
    if (!n) return;
    if (!n.drive_sync.progress?.running) { clearInterval(vidPoll); viewMedia(); return; }
    const el = $("#vprog"); if (el) el.innerHTML = progressText(n.drive_sync.progress);
  }, 4000);
  const imp = $("#vimport");
  if (imp) imp.onclick = async () => {
    imp.disabled = true; $("#vimsg").textContent = "Checking the folder…";
    try { const r = await api("/api/videos/import", { method: "POST" }); $("#vimsg").textContent = `${r.imported.length} imported, ${r.skipped.length} skipped.`; if (r.imported.length) setTimeout(viewMedia, 1200); else imp.disabled = false; }
    catch (e) { $("#vimsg").textContent = "Import failed: " + e.message; imp.disabled = false; }
  };
  $("#vform").onsubmit = async (ev) => {
    ev.preventDefault();
    const file = $("#vfile").files[0]; if (!file) return;
    const msg = $("#vmsg2"); msg.textContent = "Reading video length…";
    const duration = await new Promise((res) => { const v = document.createElement("video"); v.preload = "metadata"; v.onloadedmetadata = () => res(v.duration); v.onerror = () => res(null); v.src = URL.createObjectURL(file); });
    const p = new URLSearchParams({ filename: file.name });
    const set = (k, v) => { if (v) p.set(k, v); };
    set("zone", $("#vzone").value); set("floor", $("#vfloor").value); set("area", $("#varea").value); set("room", $("#vroom").value);
    set("recorded_at", $("#vwhen").value); set("note", $("#vnote2").value); if (duration && isFinite(duration)) p.set("duration_s", duration.toFixed(1));
    msg.textContent = `Uploading ${(file.size / 1048576).toFixed(1)} MB…`;
    try { const v = await api(`/api/videos?${p}`, { method: "POST", body: file, headers: { "Content-Type": "application/octet-stream" } }); location.hash = `#/video/${v.video_id}`; }
    catch (e) { msg.textContent = "Upload failed: " + e.message; }
  };
}

